import subprocess
import json
import os

# Test the TokenBucket implementation
code = '''
const { TokenBucket } = require('./kova.js');

// Test 1: Basic construction and initial state
console.log('=== Test 1: Basic construction ===');
const bucket = new TokenBucket({ capacity: 10, refillPerSecond: 5 });
console.log('Initial available:', bucket.available());
console.log('Expected: 10');

// Test 2: tryTake success
console.log('\n=== Test 2: tryTake success ===');
console.log('tryTake(3):', bucket.tryTake(3));
console.log('available after:', bucket.available());
console.log('Expected: true, 7');

// Test 3: tryTake failure
console.log('\n=== Test 3: tryTake failure ===');
console.log('tryTake(10):', bucket.tryTake(10));
console.log('available after:', bucket.available());
console.log('Expected: false, 7');

// Test 4: msUntil
console.log('\n=== Test 4: msUntil ===');
console.log('msUntil(10):', bucket.msUntil(10));
console.log('Expected: ceil((10-7)/5 * 1000) = 600');

// Test 5: Fake clock - time advances
console.log('\n=== Test 5: Fake clock ===');
let fakeTime = 1000;
const fakeNow = () => fakeTime;
const bucket2 = new TokenBucket({ capacity: 10, refillPerSecond: 10, now: fakeNow });
console.log('Initial:', bucket2.available());
fakeTime += 500; // 0.5 seconds
console.log('After 500ms:', bucket2.available());
console.log('Expected: 10 (capped at capacity)');
fakeTime += 500; // 1 second total
console.log('After 1000ms:', bucket2.available());
console.log('Expected: 10');

// Test 6: Clock going backwards
console.log('\n=== Test 6: Clock going backwards ===');
fakeTime = 2000;
const bucket3 = new TokenBucket({ capacity: 10, refillPerSecond: 10, now: fakeNow });
console.log('Initial:', bucket3.available());
fakeTime = 1500; // Clock goes back
console.log('After clock goes back:', bucket3.available());
console.log('Expected: 10 (no change, max time preserved)');
fakeTime = 3000; // Clock jumps forward past max
console.log('After clock jumps forward:', bucket3.available());
console.log('Expected: 10');

// Test 7: Edge cases - validation
console.log('\n=== Test 7: Validation ===');
try {
  new TokenBucket({ capacity: 0, refillPerSecond: 1 });
  console.log('FAIL: Should throw for capacity=0');
} catch (e) {
  console.log('PASS: Throws for capacity=0:', e.message);
}

try {
  new TokenBucket({ capacity: 10, refillPerSecond: -1 });
  console.log('FAIL: Should throw for negative refill');
} catch (e) {
  console.log('PASS: Throws for negative refill:', e.message);
}

try {
  bucket.tryTake(0);
  console.log('FAIL: Should throw for n=0');
} catch (e) {
  console.log('PASS: Throws for n=0:', e.message);
}

try {
  bucket.tryTake(-1);
  console.log('FAIL: Should throw for n=-1');
} catch (e) {
  console.log('PASS: Throws for n=-1:', e.message);
}

try {
  bucket.msUntil(Infinity);
  console.log('FAIL: Should throw for n=Infinity');
} catch (e) {
  console.log('PASS: Throws for n=Infinity:', e.message);
}

// Test 8: n > capacity returns Infinity
console.log('\n=== Test 8: n > capacity ===');
console.log('msUntil(20) with capacity 10:', bucket.msUntil(20));
console.log('Expected: Infinity');

// Test 9: refillPerSecond = 0
console.log('\n=== Test 9: refillPerSecond = 0 ===');
const bucket4 = new TokenBucket({ capacity: 10, refillPerSecond: 0 });
bucket4.tryTake(5);
console.log('msUntil(10) with refillPerSecond=0:', bucket4.msUntil(10));
console.log('Expected: Infinity');

// Test 10: Fractional tokens
console.log('\n=== Test 10: Fractional tokens ===');
fakeTime = 0;
const bucket5 = new TokenBucket({ capacity: 10, refillPerSecond: 1, now: fakeNow });
console.log('Initial:', bucket5.available());
fakeTime = 500; // 0.5 seconds
console.log('After 500ms:', bucket5.available());
console.log('Expected: 10 (capped)');
bucket5.tryTake(10);
fakeTime = 1000; // 1 second after last refill
console.log('After 1s:', bucket5.available());
console.log('Expected: 1');

console.log('\n=== All tests completed ===');
'''

result = subprocess.run(['node', '-e', code], capture_output=True, text=True, cwd='C:\\AI\\benchmark\\v2\\results-umay\\sandboxes\\umay-akilli__dusunme\\kod-kova-js')
print('STDOUT:')
print(result.stdout)
if result.stderr:
    print('STDERR:')
    print(result.stderr)
print('Exit code:', result.returncode)

